## Purpose

This question evaluates practical accessibility implementation in SwiftUI, lightweight persistence strategies, and architectural awareness for beginner-level candidates.

## Key Concepts

- SwiftUI accessibility modifiers (`accessibilityLabel`, `accessibilityHint`, `accessibilityValue`)
- Codable persistence to the app's Documents directory
- MVVM architecture with a minimal data model
- Dynamic Type support and color-contrast considerations (WCAG AA compliance)

## Code Example

```swift
struct Note: Codable, Identifiable {
    let id: UUID
    let title: String
    let tag: String  // e.g., "blue", "red", "green"
}

class NotesStore: ObservableObject {
    @Published var notes: [Note] = []

    private var documentsURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("notes.json")
    }

    init() { loadNotes() }

    func loadNotes() {
        guard let data = try? Data(contentsOf: documentsURL),
              let decoded = try? JSONDecoder().decode([Note].self, from: data) else { return }
        notes = decoded
    }

    func saveNotes() {
        guard let data = try? JSONEncoder().encode(notes) else { return }
        try? data.write(to: documentsURL)
    }
}

struct NoteRow: View {
    let note: Note

    var body: some View {
        HStack {
            VStack(alignment: .leading) {
                Text(note.title)
                    .font(.body)
                    .dynamicTypeSize(...(.accessibility3))

                Text(note.tag.capitalized)
                    .font(.caption)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 4)
                    .background(tagColor(note.tag))
                    .foregroundColor(tagTextColor(note.tag))
                    .clipShape(Capsule())
            }
            Spacer()
        }
        .padding(.vertical, 8)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(note.title), tagged \(note.tag)")
        .accessibilityHint("Double tap to open this note")
    }

    private func tagColor(_ tag: String) -> Color {
        switch tag.lowercased() {
        case "blue":   return Color(red: 0.0, green: 0.48, blue: 1.0)
        case "green":  return Color(red: 0.18, green: 0.8, blue: 0.25)
        case "red":    return Color(red: 0.9, green: 0.2, blue: 0.2)
        default:       return .gray
        }
    }

    private func tagTextColor(_ tag: String) -> Color {
        return .white  // High contrast against all tag colors
    }
}

struct ContentView: View {
    @StateObject private var store = NotesStore()

    var body: some View {
        NavigationStack {
            List(store.notes) { note in
                NoteRow(note: note)
            }
        }
    }
}
```

## Test Plan

1. **Accessibility Audit**: Verify VoiceOver reads labels and hints correctly for each row
2. **Dynamic Type**: Test with largest accessibility sizes to confirm layout remains usable
3. **Contrast Validation**: Use accessibility inspector or contrast checker to verify WCAG AA compliance (4.5:1 ratio)
4. **Persistence**: Confirm notes survive app restart by adding a note, killing the app, and relaunching
5. **Unit Tests**: Test `Note` Codable encoding/decoding and `NotesStore` save/load roundtrip

## Why This Is Asked
This question tests hands-on iOS fundamentals: camera usage with AVFoundation, barcode and QR code scanning, simple data modeling with Codable, and local file persistence. It also evaluates the candidate's ability to design a smooth UX flow that transitions naturally between scanning and reviewing results.

## Key Concepts
- **AVFoundation capture session and metadata output** — Configure an `AVCaptureSession` with an `AVCaptureMetadataOutput` to detect barcode and QR code symbologies.
- **Codable persistence in the Documents directory** — Encode and decode a `[Product]` array to a JSON file for lightweight local storage.
- **SwiftUI state management and List filtering** — Use `@State` or `@ObservableObject` to drive a searchable, filterable list of scanned products.
- **Camera UX** — Handle camera permissions gracefully, resume the capture session after each scan, and provide clear user feedback.

## Code Example
```swift
import SwiftUI
import AVFoundation

// MARK: - Model

struct Product: Codable, Identifiable {
    let id: String
    let name: String
    let price: Double
    var tags: [String] = []
}

// MARK: - Mock Backend

let mockProducts: [String: Product] = [
    "123456": Product(id: "123456", name: "Wireless Mouse", price: 29.99, tags: ["electronics"]),
    "789012": Product(id: "789012", name: "USB-C Cable", price: 9.99, tags: ["accessories"])
]

// MARK: - Persistence

func productsFileURL() -> URL {
    FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        .appendingPathComponent("scanned_products.json")
}

func saveProducts(_ products: [Product]) {
    if let data = try? JSONEncoder().encode(products) {
        try? data.write(to: productsFileURL())
    }
}

func loadProducts() -> [Product] {
    guard let data = try? Data(contentsOf: productsFileURL()) else { return [] }
    return (try? JSONDecoder().decode([Product].self, from: data)) ?? []
}

// MARK: - Scanner Coordinator (AVFoundation bridge)

class ScannerCoordinator: NSObject, AVCaptureMetadataOutputObjectsDelegate {
    var onCodeScanned: ((String) -> Void)?

    func metadataOutput(_ output: AVCaptureMetadataOutput,
                        didOutput metadataObjects: [AVMetadataObject],
                        from connection: AVCaptureConnection) {
        if let object = metadataObjects.first as? AVMetadataMachineReadableCodeObject,
           let value = object.stringValue {
            onCodeScanned?(value)
        }
    }
}

// MARK: - SwiftUI Views (minimal sketch)

struct ContentView: View {
    @State private var scannedProducts: [Product] = loadProducts()
    @State private var searchText = ""
    @State private var selectedTag: String?
    @State private var isScanning = true

    var filteredProducts: [Product] {
        scannedProducts.filter { product in
            (searchText.isEmpty || product.name.localizedCaseInsensitiveContains(searchText)) &&
            (selectedTag == nil || product.tags.contains(selectedTag!))
        }
    }

    var body: some View {
        NavigationStack {
            if isScanning {
                // Placeholder for the camera preview wrapped via UIViewRepresentable
                Text("Camera Preview")
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color.black)
            } else {
                List(filteredProducts) { product in
                    HStack {
                        Text(product.name)
                        Spacer()
                        Text(String(format: "$%.2f", product.price))
                    }
                }
                .searchable(text: $searchText, prompt: "Search by name")
            }
        }
    }

    func handleScan(_ code: String) {
        guard let product = mockProducts[code] else { return }
        scannedProducts.append(product)
        saveProducts(scannedProducts)
        // Briefly show the result, then resume scanning
        isScanning = false
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            isScanning = true
        }
    }
}
```

## Follow-Up Questions
- How would you handle camera permission denials and guide the user to Settings?
- What changes are needed to replace the mock dictionary with a real network call?
- How could you migrate from file-based JSON persistence to Core Data or SwiftData as the app grows?
- What strategies would you use to prevent duplicate scans in rapid succession?

## Why This Is Asked
Tests ability to design an offline-first image pipeline with robust caching, memory management, and accessibility in a real UI scenario.

## Key Concepts
- Two-tier caching (memory + disk)
- LRU eviction under memory pressure
- Prefetching and cancellation tied to visible cells
- Accessibility: Dynamic Type and VoiceOver labels
- Async/await data loading and main-thread UI updates

## Code Example
```swift
import UIKit

actor ImageLoader {
    private let memCache = NSCache<NSString, UIImage>()
    private let fileManager = FileManager.default
    private let diskDir: URL

    init(diskFolder: URL) { self.diskDir = diskFolder }

    func load(from url: URL) async -> UIImage? {
        let key = url.absoluteString as NSString
        if let image = memCache.object(forKey: key) { return image }
        let path = diskDir.appendingPathComponent(url.lastPathComponent)
        if let data = try? Data(contentsOf: path), let image = UIImage(data: data) {
            memCache.setObject(image, forKey: key)
            return image
        }
        guard let (data, _) = try? await URLSession.shared.data(from: url),
              let image = UIImage(data: data) else { return nil }
        memCache.setObject(image, forKey: key)
        try? data.write(to: path)
        return image
    }
}
```
